<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue';
import { usePreferencesStore } from '../stores/preferences';
import { useResource } from '../composables/resource';
import { record, text } from '../services/validation';
import UiButton from './UiButton.vue';
import FramePicker from './FramePicker.vue';
import StatusSlot from './StatusSlot.vue';
const prefs = usePreferencesStore(), barrage = ref<InstanceType<typeof FramePicker> | null>(null), media = ref<InstanceType<typeof FramePicker> | null>(null), status = ref('');
let clip: HTMLAudioElement | undefined;
const version = useResource(async request => { const value = text(record(await request('/api/version')).version); if (!/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.test(value) || value.length > 30) throw Error('版本資料格式不正確'); return value; });
void version.load();
function theme(event: Event) { const value = (event.target as HTMLSelectElement).value; if (value === 'auto' || value === 'light' || value === 'dark') prefs.setTheme(value); }
function audio(kind: 'music' | 'effects', event: Event, volume = false) { const input = event.target as HTMLInputElement; window.AudioSettings?.set(kind, volume ? { volume: Number(input.value) / 100 } : { enabled: input.checked }, { gesture: true }); status.value = ''; }
function barrages(event: Event) { window.MotionPolicy?.set({ barrages: (event.target as HTMLInputElement).checked }); }
function frames(event: Event) { window.BarrageFrames?.set({ enabled: (event.target as HTMLInputElement).checked }); }
function preview() { if (clip) window.AudioSettings?.stopEffect(clip); status.value = ''; clip = window.AudioSettings?.playEffect?.('confirm', { onError: () => { status.value = '無法播放音效，請再試一次。'; } }); }
onBeforeUnmount(() => { if (clip) window.AudioSettings?.stopEffect(clip); });
</script>
<template><div class="vue-game-preferences"><p>全遊戲共用 · 只調整你的體驗</p><label>外觀模式<select :value="prefs.color?.preference || 'auto'" @change="theme"><option value="auto">跟隨系統</option><option value="light">亮色模式</option><option value="dark">深色模式</option></select></label><section v-for="kind in (['music', 'effects'] as const)" :key="kind" class="vue-preference-group"><label class="vue-preference-switch"><span>{{ kind === 'music' ? '背景音樂' : '遊戲音效' }}</span><input type="checkbox" role="switch" :checked="prefs.audio?.[kind].enabled" :aria-label="'開啟' + (kind === 'music' ? '背景音樂' : '遊戲音效')" @change="audio(kind, $event)"></label><label class="vue-preference-volume"><span class="ui-sr-only">{{ kind === 'music' ? '背景音樂' : '遊戲音效' }}音量</span><input type="range" min="0" max="100" :value="Math.round((prefs.audio?.[kind].volume || 0) * 100)" @input="audio(kind, $event, true)"><output>{{ Math.round((prefs.audio?.[kind].volume || 0) * 100) }}%</output></label><UiButton v-if="kind === 'effects'" icon="sound" label="試聽音效" :disabled="!prefs.audio?.effects.enabled || !prefs.audio.effects.volume" @click="preview" /></section><section class="vue-preference-group"><label class="vue-preference-switch"><span>遊戲動畫</span><input type="checkbox" role="switch" :checked="prefs.motion?.enabled" @change="prefs.setMotion(($event.target as HTMLInputElement).checked)"></label><label class="vue-preference-switch"><span>文字與 emoji 彈幕</span><input type="checkbox" role="switch" :checked="prefs.motion?.barrages" @change="barrages"></label><p>{{ prefs.motion?.reduced ? '系統已減少動態；結果保留，彈幕改為靜態。' : '關閉動畫仍保留結果；彈幕可另外隱藏。' }}</p></section><section class="vue-preference-group"><label class="vue-preference-switch"><span>顯示彈幕框</span><input type="checkbox" role="switch" :checked="prefs.barrage?.enabled" @change="frames"></label><UiButton icon="frame" label="選擇彈幕框" :disabled="!prefs.frames.length" @click="barrage?.open($event.currentTarget as HTMLElement)" /><UiButton icon="frame" label="選擇播放器外觀" :disabled="!prefs.frames.length" @click="media?.open($event.currentTarget as HTMLElement)" /></section><StatusSlot :message="status" :error="!!status" /><footer><p>{{ version.data.value ? '版本 v' + version.data.value : version.loading.value ? '版本載入中…' : '版本暫時無法取得' }}</p><UiButton v-if="version.error.value" icon="refresh" label="重試載入版本" :disabled="version.loading.value" @click="version.load()" /></footer></div><FramePicker ref="barrage" kind="barrage" /><FramePicker ref="media" kind="media" /></template>
